def find_path(grid, start, goal):
    # Define the movements (up, down, left, right)
    movements = [(0, -1), (0, 1), (-1, 0), (1, 0)]

    # Find the coordinates of the start and goal states
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == start:
                start_coords = (i, j)
            elif grid[i][j] == goal:
                goal_coords = (i, j)

    # Perform BFS to find the shortest path
    queue = [(start_coords, [start])]
    visited = set([start_coords])

    while queue:
        (x, y), path = queue.pop(0)

        if (x, y) == goal_coords:
            return path

        for dx, dy in movements:
            nx, ny = x + dx, y + dy

            # Check if the new coordinates are within the grid boundaries
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                # Check if the new cell is not an obstacle and has not been visited
                if grid[nx][ny] != "X" and (nx, ny) not in visited:
                    # Find the value of the new cell
                    for i in range(len(grid)):
                        for j in range(len(grid[i])):
                            if (i, j) == (nx, ny):
                                new_cell_value = grid[i][j]

                    queue.append(((nx, ny), path + [new_cell_value]))
                    visited.add((nx, ny))

    return None


